CREATE TABLE IF NOT EXISTS authentication (id BINARY(16) PRIMARY KEY, user_id BINARY(16) NOT NULL, uuid BINARY(16) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
ALTER TABLE authentication ADD CONSTRAINT authentication_user_id_unique UNIQUE (user_id);
ALTER TABLE authentication ADD CONSTRAINT authentication_uuid_unique UNIQUE (uuid);
CREATE TABLE IF NOT EXISTS auth_device (id BINARY(16) PRIMARY KEY, user_auth_id BINARY(16) NOT NULL, device_uuid BINARY(16) NOT NULL, device_name VARCHAR(255) NOT NULL, `language` INT NOT NULL, refresh_token_id BINARY(16) NULL, refresh_token_hash VARCHAR(64) NULL, refresh_token_expires_at TIMESTAMP(6) NULL, previous_refresh_token_id BINARY(16) NULL, previous_refresh_token_hash VARCHAR(64) NULL, is_signed_in BOOLEAN NOT NULL, last_log_in_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_auth_device_user_auth_id__id FOREIGN KEY (user_auth_id) REFERENCES authentication(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX auth_device_user_auth_id ON auth_device (user_auth_id);
ALTER TABLE auth_device ADD CONSTRAINT auth_device_user_auth_id_device_uuid_unique UNIQUE (user_auth_id, device_uuid);
CREATE TABLE IF NOT EXISTS passkey_credentials (id BINARY(16) PRIMARY KEY, auth_id BINARY(16) NOT NULL, `name` VARCHAR(255) NOT NULL, cred_descriptor_id VARBINARY(24) NOT NULL, cred_descriptor_type VARCHAR(255) NOT NULL, cred_descriptor_transports VARCHAR(255) NOT NULL, public_key text NOT NULL, signature_count BIGINT NOT NULL, discoverable BOOLEAN NOT NULL, backup_eligible BOOLEAN NOT NULL, backed_up BOOLEAN NOT NULL, attestation_object VARBINARY(255) NOT NULL, client_data VARCHAR(512) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, last_used_at TIMESTAMP(6) NOT NULL, CONSTRAINT fk_passkey_credentials_auth_id__id FOREIGN KEY (auth_id) REFERENCES authentication(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE passkey_credentials ADD CONSTRAINT passkey_credentials_auth_id_cred_descriptor_id_unique UNIQUE (auth_id, cred_descriptor_id);
CREATE TABLE IF NOT EXISTS signing_key (id BINARY(16) PRIMARY KEY, public_key text NOT NULL, private_key text NOT NULL, status INT NOT NULL, created_at TIMESTAMP(6) NOT NULL, retired_at TIMESTAMP(6) NULL);
CREATE INDEX signing_key_status ON signing_key (status);
